{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "weather_card",
        "packing_card",
        "actions_card",
        "sources_card"
      ]
    },
    "weather_card": {
      "type": "Card",
      "props": {},
      "children": [
        "weather_header_stack",
        "weather_description"
      ]
    },
    "weather_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": [
        "weather_icon",
        "weather_title"
      ]
    },
    "weather_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000274_01_1_cloud-drizzle.svg"
      },
      "children": []
    },
    "weather_title": {
      "type": "Text",
      "props": {
        "text": "Seattle Spring Weather & Packing Overview",
        "variant": "h2"
      },
      "children": []
    },
    "weather_description": {
      "type": "Text",
      "props": {
        "text": "For your outdoor-focused trip to Seattle from May 1st to May 5th, expect cool, damp spring weather. Daily highs will be between 10-15°C (50-59°F) and lows between 5-8°C (41-46°F), with a 60% chance of rain each day. Layering and waterproof gear will be essential to stay comfortable."
      },
      "children": []
    },
    "packing_card": {
      "type": "Card",
      "props": {},
      "children": [
        "packing_header_stack",
        "packing_intro",
        "outerwear_stack",
        "midlayers_stack",
        "baselayers_stack",
        "bottoms_stack",
        "footwear_stack",
        "accessories_stack"
      ]
    },
    "packing_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": [
        "packing_icon",
        "packing_title"
      ]
    },
    "packing_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000274_01_2_backpack.svg"
      },
      "children": []
    },
    "packing_title": {
      "type": "Text",
      "props": {
        "text": "Outdoor Trip Packing Recommendations",
        "variant": "h2"
      },
      "children": []
    },
    "packing_intro": {
      "type": "Text",
      "props": {
        "text": "Given the forecast, prioritize versatile layers and reliable rain protection for your outdoor activities."
      },
      "children": []
    },
    "outerwear_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "outerwear_title",
        "outerwear_list"
      ]
    },
    "outerwear_title": {
      "type": "Text",
      "props": {
        "text": "Outerwear",
        "variant": "h3"
      },
      "children": []
    },
    "outerwear_list": {
      "type": "List",
      "props": {},
      "children": [
        "outerwear_item1",
        "outerwear_item2"
      ]
    },
    "outerwear_item1": {
      "type": "Text",
      "props": {
        "text": "Waterproof & Windproof Jacket: A breathable shell is crucial for rain and wind protection."
      },
      "children": []
    },
    "outerwear_item2": {
      "type": "Text",
      "props": {
        "text": "Light Insulated Jacket (Optional): A packable down or synthetic jacket for colder mornings or evenings."
      },
      "children": []
    },
    "midlayers_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "midlayers_title",
        "midlayers_list"
      ]
    },
    "midlayers_title": {
      "type": "Text",
      "props": {
        "text": "Mid-layers",
        "variant": "h3"
      },
      "children": []
    },
    "midlayers_list": {
      "type": "List",
      "props": {},
      "children": [
        "midlayers_item1",
        "midlayers_item2"
      ]
    },
    "midlayers_item1": {
      "type": "Text",
      "props": {
        "text": "Fleece Jacket or Sweater (2-3): Provides warmth over your base layer."
      },
      "children": []
    },
    "midlayers_item2": {
      "type": "Text",
      "props": {
        "text": "Long-Sleeve Shirts (2-3): Moisture-wicking materials are best for active days."
      },
      "children": []
    },
    "baselayers_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "baselayers_title",
        "baselayers_list"
      ]
    },
    "baselayers_title": {
      "type": "Text",
      "props": {
        "text": "Base Layers",
        "variant": "h3"
      },
      "children": []
    },
    "baselayers_list": {
      "type": "List",
      "props": {},
      "children": [
        "baselayers_item1",
        "baselayers_item2"
      ]
    },
    "baselayers_item1": {
      "type": "Text",
      "props": {
        "text": "Short-Sleeve T-shirts (3-4): Quick-drying fabrics (synthetic or merino wool)."
      },
      "children": []
    },
    "baselayers_item2": {
      "type": "Text",
      "props": {
        "text": "Long Underwear (1 set): For added warmth if you tend to get cold or for very early mornings/late evenings."
      },
      "children": []
    },
    "bottoms_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "bottoms_title",
        "bottoms_list"
      ]
    },
    "bottoms_title": {
      "type": "Text",
      "props": {
        "text": "Bottoms",
        "variant": "h3"
      },
      "children": []
    },
    "bottoms_list": {
      "type": "List",
      "props": {},
      "children": [
        "bottoms_item1",
        "bottoms_item2",
        "bottoms_item3"
      ]
    },
    "bottoms_item1": {
      "type": "Text",
      "props": {
        "text": "Hiking Pants (2): Quick-drying, comfortable, and possibly water-resistant. Avoid cotton."
      },
      "children": []
    },
    "bottoms_item2": {
      "type": "Text",
      "props": {
        "text": "Waterproof Rain Pants (1): Essential for sustained rain during outdoor activities."
      },
      "children": []
    },
    "bottoms_item3": {
      "type": "Text",
      "props": {
        "text": "Casual Pants/Jeans (1): For evenings or less active times."
      },
      "children": []
    },
    "footwear_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "footwear_title",
        "footwear_list"
      ]
    },
    "footwear_title": {
      "type": "Text",
      "props": {
        "text": "Footwear",
        "variant": "h3"
      },
      "children": []
    },
    "footwear_list": {
      "type": "List",
      "props": {},
      "children": [
        "footwear_item1",
        "footwear_item2",
        "footwear_item3"
      ]
    },
    "footwear_item1": {
      "type": "Text",
      "props": {
        "text": "Waterproof Hiking Boots: Comfortable, broken-in, and good traction for trails."
      },
      "children": []
    },
    "footwear_item2": {
      "type": "Text",
      "props": {
        "text": "Water-Resistant Walking Shoes: For urban exploration or lighter activities."
      },
      "children": []
    },
    "footwear_item3": {
      "type": "Text",
      "props": {
        "text": "Wool or Synthetic Socks (4-5 pairs): Keeps feet dry and prevents blisters."
      },
      "children": []
    },
    "accessories_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "accessories_title",
        "accessories_list"
      ]
    },
    "accessories_title": {
      "type": "Text",
      "props": {
        "text": "Accessories",
        "variant": "h3"
      },
      "children": []
    },
    "accessories_list": {
      "type": "List",
      "props": {},
      "children": [
        "accessories_item1",
        "accessories_item2",
        "accessories_item3",
        "accessories_item4",
        "accessories_item5"
      ]
    },
    "accessories_item1": {
      "type": "Text",
      "props": {
        "text": "Waterproof Backpack Cover or Dry Bags: To protect electronics and essentials from rain."
      },
      "children": []
    },
    "accessories_item2": {
      "type": "Text",
      "props": {
        "text": "Hat (warm and/or waterproof): For sun protection and warmth."
      },
      "children": []
    },
    "accessories_item3": {
      "type": "Text",
      "props": {
        "text": "Gloves (lightweight, waterproof): For colder, rainy conditions."
      },
      "children": []
    },
    "accessories_item4": {
      "type": "Text",
      "props": {
        "text": "Sunglasses: Even on cloudy days, UV protection is important."
      },
      "children": []
    },
    "accessories_item5": {
      "type": "Text",
      "props": {
        "text": "Reusable Water Bottle: Stay hydrated on trails."
      },
      "children": []
    },
    "actions_card": {
      "type": "Card",
      "props": {},
      "children": [
        "actions_header_stack",
        "actions_button_stack"
      ]
    },
    "actions_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": [
        "actions_icon",
        "actions_title"
      ]
    },
    "actions_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000274_01_3_gear.svg"
      },
      "children": []
    },
    "actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "actions_button_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "view_weather_button",
        "find_gear_button"
      ]
    },
    "view_weather_button": {
      "type": "Button",
      "props": {
        "label": "View Detailed Weather Forecast"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.accuweather.com/en/us/seattle/98104/weather-forecast/350438"
          }
        }
      },
      "children": []
    },
    "find_gear_button": {
      "type": "Button",
      "props": {
        "label": "Find Waterproof Outdoor Gear"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.rei.com/c/waterproof-clothing"
          }
        }
      },
      "children": []
    },
    "sources_card": {
      "type": "Card",
      "props": {},
      "children": [
        "sources_header_stack",
        "sources_list"
      ]
    },
    "sources_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": [
        "sources_icon",
        "sources_title"
      ]
    },
    "sources_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000274_01_4_info.svg"
      },
      "children": []
    },
    "sources_title": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sources_list": {
      "type": "List",
      "props": {},
      "children": [
        "source_weather",
        "source_packing"
      ]
    },
    "source_weather": {
      "type": "Text",
      "props": {
        "text": "Weather data from AccuWeather.com"
      },
      "children": []
    },
    "source_packing": {
      "type": "Text",
      "props": {
        "text": "Packing recommendations based on general outdoor travel advice for temperate, rainy climates."
      },
      "children": []
    }
  }
}
